<script setup>
import { onMounted } from 'vue';
import { useTranscriptionStore } from '../store';
const store = useTranscriptionStore();
onMounted(() => store.load());
</script>
<template><div class="history-shell"><header><RouterLink to="/transcriptions" class="brand"><span class="brand-mark">d</span><span>ruang<span class="brand-light">dengar</span></span></RouterLink><RouterLink class="submit-button back-link" to="/transcriptions">Transkripsi baru <span>→</span></RouterLink></header><main class="content-wrap"><section class="recordings"><div class="recordings-heading"><div><div class="eyebrow"><span class="eyebrow-line"></span>ARSIP WORKSPACE</div><h2>Rekaman terbaru</h2></div><span class="record-count">{{ store.pagination?.total ?? 0 }} rekaman</span></div><div v-if="store.loading" role="status" class="empty-state">Memuat riwayat…</div><div v-else-if="store.error" role="alert" class="notice error">{{ store.error }}</div><div v-else-if="store.items.length" class="record-list"><article v-for="record in store.items" :key="record.id" class="record-row"><span class="record-icon">♫</span><div class="record-info"><strong>{{ record.name || record.filename }}</strong><small>{{ new Date(record.created_at).toLocaleString('id-ID') }}</small><small v-if="record.transcript">{{ record.transcript.slice(0, 180) }}</small><small v-else-if="record.status === 'failed'">Transkripsi gagal diproses.</small></div><span class="record-state">{{ record.status }}</span></article></div><div v-else class="empty-state">Belum ada rekaman.</div><div v-if="store.pagination" class="pagination"><button :disabled="store.pagination.current_page <= 1" @click="store.load(store.pagination.current_page - 1)">Sebelumnya</button><span>Halaman {{ store.pagination.current_page }} dari {{ store.pagination.last_page }}</span><button :disabled="store.pagination.current_page >= store.pagination.last_page" @click="store.load(store.pagination.current_page + 1)">Berikutnya</button></div></section></main></div></template>
